// Generate the full registry combining featured + official bulk
const generateRegistry = (): Project[] => {
  const all = [...FEATURED_PROJECTS];
  let id = 27;

  for (const proj of OFFICIAL_REGISTRY) {
    // Skip if already in featured list by name (case-insensitive)
    const exists = FEATURED_PROJECTS.some(f => f.name.toLowerCase() === proj.name.toLowerCase());
    if (!exists) {
      all.push({
        id,
        ...proj,
        duneQueryId: 1000 + id,
        graphSubgraph: `${proj.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-mantle`,
        mobulaId: proj.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
        messariSlug: proj.name.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      });
      id++;
    }
  }

  return all;
};

export const MANTLE_PROJECTS: Project[] = generateRegistry();
